/* Baixa rápida por conta/parcela, com estorno auditável. */
(function(root){'use strict';const D=root.Obras,clone=D.clone,uid=()=> 'REC-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);let api,pending=false;
function toggle(state,sourceId,type,installmentId){let s=clone(state),all=D.receivableRows(s),row=all.find(r=>r.sourceId===sourceId&&r.type===type&&(r.installmentId||'')===(installmentId||''));if(!row)throw Error('Conta ou parcela não encontrada. Atualize a página.');let before=clone(s.receipts),paid=row.balance===0;
if(!paid){let receipt={id:uid(),project:row.project,number:row.manual?'Avulso:'+sourceId:row.number,receiptType:type,...(row.manual?{receivableId:sourceId}:{}),...(installmentId?{installmentId}:{}),date:D.today(),amount:row.balance,note:'Recebimento rápido em Contas a receber.',quickReceipt:true};s=D.saveRecord(s,'receipts',receipt);}
else{let belongs=r=>row.manual?r.receivableId===sourceId:!r.receivableId&&r.project===row.project&&r.number===row.number&&(r.receiptType==='Retenção')===(type==='Retenção'),affected=s.receipts.filter(r=>belongs(r)&&(installmentId?Object.hasOwn(row.receiptAmounts||{},r.id):true)),quick=affected.filter(r=>r.quickReceipt&&(!installmentId||r.installmentId===installmentId)),ids=new Set((quick.length?quick:affected).map(r=>r.id));if(!ids.size)throw Error('Nenhum recebimento encontrado para desfazer.');let next=[];for(let r of s.receipts){if(!ids.has(r.id)){next.push(r);continue}if(installmentId&&!r.installmentId&&!quick.length){/* Preserva a distribuição antiga nas demais parcelas. */let others=all.filter(x=>x.sourceId===sourceId&&x.type===type&&x.installmentId!==installmentId&&x.receiptAmounts?.[r.id]>0);for(let [i,x]of others.entries())next.push({...clone(r),id:i===0?r.id:uid(),installmentId:x.installmentId,amount:x.receiptAmounts[r.id]});}}
s.receipts=next;D.validateReceivableInstallments(s);D.validateManualReceivables(s);D.validateMeasurementFinances(s);}
let prior=new Map(before.map(r=>[r.id,JSON.stringify(r)])),after=new Map(s.receipts.map(r=>[r.id,JSON.stringify(r)]));let changed=new Set([...prior.keys(),...after.keys()].filter(id=>prior.get(id)!==after.get(id)));s.history.unshift({id:'H-'+uid(),time:new Date().toISOString(),kind:'receivableReceiptToggle',record:sourceId,action:paid?'Recebimento desfeito pelo botão':'Marcado como recebido pelo botão',installmentId:installmentId||null,before:before.filter(r=>changed.has(r.id)),after:clone(s.receipts.filter(r=>changed.has(r.id)))});return {state:s,paid:!paid};}
async function handle(action,trigger){if(!action?.startsWith('receivable-toggle:'))return false;if(pending)return true;try{pending=true;if(trigger)trigger.disabled=true;let [type,id,part]=JSON.parse(decodeURIComponent(action.slice(18))),result=toggle(api.getState(),id,type,part);if(await api.save(result.state)===false)throw Error('O servidor não confirmou o recebimento. Atualize os dados antes de tentar novamente.');api.done(result.paid);api.toast(result.paid?'Recebimento registrado.':'Recebimento desfeito.')}catch(e){api.toast(e.message)}finally{pending=false;if(trigger)trigger.disabled=false}return true}
root.EngefexReceivableToggle={toggle,handle,init:a=>api=a,busy:()=>pending};
})(typeof window==='undefined'?globalThis:window);
